#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <limits.h>

#define MAX_PATH 4096
#define SESSION_DIR "/tmp/sessions"
#define UPLOAD_DIR "/tmp/uploads"
#define MAX_FILENAME 255
#define LISTEN_PORT 8080
#define MAX_HEADER 8192

typedef struct {
    int fd;
    struct sockaddr_in addr;
} conn_t;

/* Sanitize a path component - removes ../ and null bytes */
static int sanitize_component(const char *input, char *output, size_t outlen) {
    size_t i, j = 0;
    if (!input || !output || outlen == 0) return -1;

    for (i = 0; input[i] && j < outlen - 1; i++) {
        if (input[i] == '\0') break;
        if (input[i] == '.' && input[i+1] == '.') {
            i++; /* skip both dots */
            continue;
        }
        if (input[i] == '/' || input[i] == '\\') continue;
        output[j++] = input[i];
    }
    output[j] = '\0';
    return (int)j;
}

/* Compute a simple checksum for integrity verification */
static unsigned int compute_checksum(const char *data, size_t len) {
    unsigned int sum = 0x5A5A5A5A;
    size_t i;
    for (i = 0; i < len; i++) {
        sum ^= ((unsigned int)(unsigned char)data[i]) << ((i % 4) * 8);
        sum = (sum << 3) | (sum >> 29);
    }
    return sum;
}

/* Validate content-length header value.
 * Returns the validated length, or -1 on error.
 * Security: prevents negative lengths and oversized uploads.
 */
static int validate_content_length(const char *header_val) {
    long parsed;
    char *endptr;

    if (!header_val) return -1;

    errno = 0;
    parsed = strtol(header_val, &endptr, 10);

    if (errno != 0 || endptr == header_val || *endptr != '\0') {
        return -1;
    }

    /* Reject negative values */
    if (parsed < 0) return -1;

    /* Reject zero-length uploads */
    if (parsed == 0) return -1;

    /* Cap at reasonable upload size (10MB) */
    if (parsed > 10 * 1024 * 1024) return -1;

    return (int)parsed;
}

/* Read exactly n bytes from fd into buf.
 * Returns 0 on success, -1 on error/short read.
 */
static int read_exact(int fd, char *buf, size_t n) {
    size_t total = 0;
    while (total < n) {
        ssize_t r = read(fd, buf + total, n - total);
        if (r <= 0) return -1;
        total += (size_t)r;
    }
    return 0;
}

/* Process an upload request.
 * Format: UPLOAD <filename>\n<content-length>\n<data>
 * 
 * Security measures:
 * - Filename sanitization (no path traversal)
 * - Content-length validation
 * - Checksum verification
 * - Size limits enforced
 */
static void handle_upload(int client_fd, const char *request) {
    char filename[MAX_FILENAME + 1];
    char safe_name[MAX_FILENAME + 1];
    char filepath[MAX_PATH];
    char *content_start;
    char *newline;
    char length_str[32];
    int content_length;
    char *buffer;
    ssize_t written;
    int out_fd;
    int name_len;

    /* Parse filename */
    if (strncmp(request, "UPLOAD ", 7) != 0) {
        write(client_fd, "ERR bad command\n", 16);
        return;
    }

    const char *fname_start = request + 7;
    newline = strchr(fname_start, '\n');
    if (!newline) {
        write(client_fd, "ERR no newline\n", 15);
        return;
    }

    size_t fname_len = (size_t)(newline - fname_start);
    if (fname_len >= MAX_FILENAME) {
        write(client_fd, "ERR name too long\n", 18);
        return;
    }

    memcpy(filename, fname_start, fname_len);
    filename[fname_len] = '\0';

    /* Sanitize the filename */
    name_len = sanitize_component(filename, safe_name, sizeof(safe_name));
    if (name_len <= 0) {
        write(client_fd, "ERR bad filename\n", 17);
        return;
    }

    /* Parse content-length */
    const char *len_start = newline + 1;
    newline = strchr(len_start, '\n');
    if (!newline) {
        write(client_fd, "ERR no length\n", 14);
        return;
    }

    size_t len_len = (size_t)(newline - len_start);
    if (len_len >= sizeof(length_str)) {
        write(client_fd, "ERR length overflow\n", 20);
        return;
    }

    memcpy(length_str, len_start, len_len);
    length_str[len_len] = '\0';

    content_length = validate_content_length(length_str);
    if (content_length < 0) {
        write(client_fd, "ERR invalid length\n", 19);
        return;
    }

    content_start = (char *)(newline + 1);

    /* Build safe file path */
    int path_len = snprintf(filepath, sizeof(filepath), "%s/%s", UPLOAD_DIR, safe_name);
    if (path_len < 0 || (size_t)path_len >= sizeof(filepath)) {
        write(client_fd, "ERR path too long\n", 18);
        return;
    }

    /* Allocate buffer and read content */
    buffer = malloc((size_t)content_length + 1);
    if (!buffer) {
        write(client_fd, "ERR no memory\n", 14);
        return;
    }

    /* Copy any data already in the request buffer */
    size_t already_have = strlen(content_start);
    size_t to_copy = already_have;
    if (to_copy > (size_t)content_length) to_copy = (size_t)content_length;
    memcpy(buffer, content_start, to_copy);

    /* Read remaining data from socket */
    if ((size_t)content_length > to_copy) {
        size_t remaining = (size_t)content_length - to_copy;
        if (read_exact(client_fd, buffer + to_copy, remaining) != 0) {
            free(buffer);
            write(client_fd, "ERR read failed\n", 16);
            return;
        }
    }
    buffer[content_length] = '\0';

    /* Verify checksum - last 4 bytes are the checksum */
    if (content_length >= 4) {
        unsigned int expected_sum;
        memcpy(&expected_sum, buffer + content_length - 4, 4);
        unsigned int actual_sum = compute_checksum(buffer, content_length - 4);
        if (expected_sum != actual_sum) {
            free(buffer);
            write(client_fd, "ERR checksum mismatch\n", 22);
            return;
        }
    }

    /* Write to file - use O_NOFOLLOW to prevent symlink attacks */
    out_fd = open(filepath, O_WRONLY | O_CREAT | O_TRUNC | O_NOFOLLOW, 0644);
    if (out_fd < 0) {
        free(buffer);
        write(client_fd, "ERR open failed\n", 16);
        return;
    }

    written = write(out_fd, buffer, (size_t)content_length);
    close(out_fd);
    free(buffer);

    if (written == (ssize_t)content_length) {
        write(client_fd, "OK uploaded\n", 12);
    } else {
        write(client_fd, "ERR write failed\n", 17);
    }
}

/* Process a download request.
 * Format: DOWNLOAD <filename>\n
 * 
 * Security: validates filename, checks file exists within upload dir,
 * uses O_NOFOLLOW to prevent symlink-based attacks.
 */
static void handle_download(int client_fd, const char *request) {
    char filename[MAX_FILENAME + 1];
    char safe_name[MAX_FILENAME + 1];
    char filepath[MAX_PATH];
    char resolved_upload[PATH_MAX];
    char resolved_file[PATH_MAX];
    struct stat st;
    char *buffer;
    int in_fd;
    ssize_t bytes_read;
    int name_len;

    if (strncmp(request, "DOWNLOAD ", 9) != 0) {
        write(client_fd, "ERR bad command\n", 16);
        return;
    }

    const char *fname_start = request + 9;
    char *newline = strchr(fname_start, '\n');
    size_t fname_len;

    if (newline) {
        fname_len = (size_t)(newline - fname_start);
    } else {
        fname_len = strlen(fname_start);
    }

    if (fname_len >= MAX_FILENAME) {
        write(client_fd, "ERR name too long\n", 18);
        return;
    }

    memcpy(filename, fname_start, fname_len);
    filename[fname_len] = '\0';

    /* Sanitize */
    name_len = sanitize_component(filename, safe_name, sizeof(safe_name));
    if (name_len <= 0) {
        write(client_fd, "ERR bad filename\n", 17);
        return;
    }

    snprintf(filepath, sizeof(filepath), "%s/%s", UPLOAD_DIR, safe_name);

    /* Resolve upload dir to canonical path */
    if (realpath(UPLOAD_DIR, resolved_upload) == NULL) {
        write(client_fd, "ERR server error\n", 17);
        return;
    }

    /* Resolve requested file path */
    if (realpath(filepath, resolved_file) == NULL) {
        write(client_fd, "ERR not found\n", 14);
        return;
    }

    /* Verify resolved path starts with resolved upload dir */
    size_t upload_len = strlen(resolved_upload);
    if (strncmp(resolved_file, resolved_upload, upload_len) != 0 ||
        (resolved_file[upload_len] != '/' && resolved_file[upload_len] != '\0')) {
        write(client_fd, "ERR access denied\n", 18);
        return;
    }

    /* Use fstat on opened fd to avoid TOCTOU */
    in_fd = open(resolved_file, O_RDONLY | O_NOFOLLOW);
    if (in_fd < 0) {
        write(client_fd, "ERR open failed\n", 16);
        return;
    }

    if (fstat(in_fd, &st) != 0 || !S_ISREG(st.st_mode)) {
        close(in_fd);
        write(client_fd, "ERR not a file\n", 15);
        return;
    }

    if (st.st_size > 10 * 1024 * 1024 || st.st_size <= 0) {
        close(in_fd);
        write(client_fd, "ERR invalid size\n", 17);
        return;
    }

    buffer = malloc((size_t)st.st_size);
    if (!buffer) {
        close(in_fd);
        write(client_fd, "ERR no memory\n", 14);
        return;
    }

    bytes_read = read(in_fd, buffer, (size_t)st.st_size);
    close(in_fd);

    if (bytes_read > 0) {
        char header[64];
        int hlen = snprintf(header, sizeof(header), "DATA %zd\n", bytes_read);
        write(client_fd, header, (size_t)hlen);
        write(client_fd, buffer, (size_t)bytes_read);
    } else {
        write(client_fd, "ERR read failed\n", 16);
    }

    free(buffer);
}

static void *client_handler(void *arg) {
    conn_t *conn = (conn_t *)arg;
    int fd = conn->fd;
    char buf[MAX_HEADER];
    ssize_t n;

    free(conn);

    while ((n = recv(fd, buf, sizeof(buf) - 1, 0)) > 0) {
        buf[n] = '\0';

        if (strncmp(buf, "UPLOAD ", 7) == 0) {
            handle_upload(fd, buf);
        } else if (strncmp(buf, "DOWNLOAD ", 9) == 0) {
            handle_download(fd, buf);
        } else {
            write(fd, "ERR unknown command\n", 20);
        }
    }

    close(fd);
    return NULL;
}

int main(void) {
    int server_fd;
    struct sockaddr_in addr;
    pthread_t tid;

    mkdir(SESSION_DIR, 0700);
    mkdir(UPLOAD_DIR, 0755);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) return 1;

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons(LISTEN_PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) return 1;
    if (listen(server_fd, 16) < 0) return 1;

    while (1) {
        conn_t *conn = malloc(sizeof(conn_t));
        if (!conn) continue;

        socklen_t alen = sizeof(conn->addr);
        conn->fd = accept(server_fd, (struct sockaddr *)&conn->addr, &alen);
        if (conn->fd < 0) {
            free(conn);
            continue;
        }

        pthread_create(&tid, NULL, client_handler, conn);
        pthread_detach(tid);
    }

    return 0;
}
